CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(320) NOT NULL, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, email_verified BOOLEAN NOT NULL DEFAULT FALSE, platform_role VARCHAR(20) NOT NULL DEFAULT 'USER', status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX uq_accounts_email ON accounts (lower(email));
CREATE TABLE apps (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_account_id UUID NOT NULL REFERENCES accounts(id), name VARCHAR(100) NOT NULL, publishable_key VARCHAR(80) NOT NULL UNIQUE, secret_key_hash VARCHAR(64) NOT NULL, secret_key_hint VARCHAR(12) NOT NULL, allowed_origins TEXT[] NOT NULL DEFAULT '{}', verify_email_url VARCHAR(500), reset_password_url VARCHAR(500), require_email_verification BOOLEAN NOT NULL DEFAULT TRUE, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_apps_owner ON apps (owner_account_id);
CREATE TABLE app_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE, email VARCHAR(320) NOT NULL, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, email_verified BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX uq_app_users_app_email ON app_users (app_id, lower(email));
CREATE TABLE roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE, name VARCHAR(60) NOT NULL, description VARCHAR(255), is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (app_id, name));
CREATE UNIQUE INDEX uq_roles_one_default_per_app ON roles (app_id) WHERE is_default;
CREATE TABLE permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), app_id UUID NOT NULL REFERENCES apps(id) ON DELETE CASCADE, key VARCHAR(100) NOT NULL, description VARCHAR(255), UNIQUE (app_id, key));
CREATE TABLE role_permissions (role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY (role_id, permission_id));
CREATE TABLE app_user_roles (app_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE, assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (app_user_id, role_id));
CREATE TABLE sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), account_id UUID REFERENCES accounts(id) ON DELETE CASCADE, app_user_id UUID REFERENCES app_users(id) ON DELETE CASCADE, refresh_token_hash VARCHAR(64) NOT NULL UNIQUE, previous_refresh_hash VARCHAR(64), ip_address VARCHAR(45), user_agent VARCHAR(255), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_active_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, CONSTRAINT chk_sessions_one_subject CHECK (num_nonnulls(account_id, app_user_id) = 1));
CREATE INDEX idx_sessions_account ON sessions (account_id) WHERE revoked_at IS NULL;
CREATE INDEX idx_sessions_app_user ON sessions (app_user_id) WHERE revoked_at IS NULL;
CREATE TABLE email_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), account_id UUID REFERENCES accounts(id) ON DELETE CASCADE, app_user_id UUID REFERENCES app_users(id) ON DELETE CASCADE, type VARCHAR(20) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT chk_email_tokens_one_subject CHECK (num_nonnulls(account_id, app_user_id) = 1));
CREATE TABLE audit_logs (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, app_id UUID, actor_account_id UUID, actor_app_user_id UUID, actor_type VARCHAR(20) NOT NULL, action VARCHAR(60) NOT NULL, ip_address VARCHAR(45), metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE signing_keys (kid VARCHAR(40) PRIMARY KEY, public_key_pem TEXT NOT NULL, private_key_enc TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
